def pages():
    out = []
    for c in CITIES:
        groups = [("", [(n, "Copy all", s) for n, s in c["sets"]])]
        others = [f"/hashtags/{x['slug']}/" for x in CITIES if x["slug"] != c["slug"]][:4]
        out.append(dict(path=f"/hashtags/{c['slug']}/", section="hashtags", crumb=f"{c['name']} hashtags",
                        title=f"{c['name']} Real Estate Hashtags — 10 Copy-Ready Sets | ListingKit",
                        meta=f"Copy-ready real estate hashtags for {c['name']}, {c['country']}: area, property type, rental, land, shortlet, luxury and TikTok sets for Instagram and TikTok posts.",
                        h1=f"{c['name']} real estate hashtags", eyebrow=f"Hashtags · {c['country']}",
                        lede=f"Ten grouped hashtag sets for {c['name']} property posts. Mix one broad set with one area set and one property-type set.",
                        intro=[c["context"],
                               "We haven't verified post counts for every tag, and popularity changes. Before you rely on a set, tap a few tags in Instagram or TikTok to check they're active and not spammy."],
                        groups=[("", groups[0][1])], groups_title=f"{c['name']} hashtag sets",
                        tips=["On Instagram, use 5–15 hashtags that genuinely match the post: one broad set, one area set, one type set.",
                              "On TikTok, 3–5 tags is enough; the caption and on-screen text matter more.",
                              "Rotate sets between posts so you don't paste the identical block every time.",
                              "Add one branded tag of your own (for example #[YourName]Homes) so clients can find all your listings.",
                              "Avoid unrelated trending tags. They bring views but not buyers."],
                        tips_title="How to use these hashtags",
                        faq=[(f"What are the best real estate hashtags in {c['name']}?", f"Combine a broad tag like {c['sets'][0][1].split()[0]} with neighbourhood tags and a property-type tag. Specific beats popular for finding real buyers."),
                             ("How many hashtags should a property post have?", "5 to 15 on Instagram and 3 to 5 on TikTok works well for most agents."),
                             ("Do hashtags still work on Instagram?", "They help categorise your post and reach people browsing a tag, but the photo, the first caption line and your call to action matter more."),
                             ("Can ListingKit add hashtags automatically?", "Yes. The generator adds local hashtags to every Instagram and TikTok caption based on the property's location.")],
                        related=others + ["/captions/just-listed/", "/captions/shortlet/"], blurb=c["context"][:110]))
    return out
